pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint256[] memory v) public {
        // Assume _tos and v have length > 0, matching require
        vm.assume(_tos.length > 0 && _tos.length == v.length);
        // Bound v elements to avoid overflow in multiplication check
        for (uint i = 0; i < v.length; i++) {
            v[i] = bound(v[i], 0, type(uint256).max / 1000000000000000000);
        }
        // Prank as the allowed sender (0x9797...)
        address allowedSender = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        vm.prank(allowedSender);
        // Call transfer; revert is expected on overflow, but if it succeeds, from() must be unchanged
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.transfer.selector, _tos, v));
        if (success) {
            assertTrue(c.from() == allowedSender, "from should remain unchanged");
        }
    }
}

